401:     ch = commentWhitespace(true);
402: 
403:     if (!isQuote(ch)) {
404:       return syntaxError();
405:     }
406: 
407:     readImportString(startPos, ch, false);
408:   }
409:   else {
410:     if (!(ch == '"' || ch == '\'' || ch == '*')) {
411:       // no space after "import" -> not an import keyword
412:       if (pos == startPos + 6) {
413:         pos--;
414:         return;
415:       }
416:     }
417:     // import defer * as foo mandates *;
418:     // import statement only permitted at base-level
419:     if (phase_keyword == 2 && ch != '*' || openTokenDepth != 0) {
420:       pos--;
421:       return;
422:     }
423:     while (pos < end) {
424:       ch = *pos;
425:       if (isQuote(ch)) {
426:         readImportString(startPos, ch, phase_keyword);
427:         return;
428:       }
429:       pos++;
430:     }
431:     syntaxError();
432:   }
