782: char16_t readExportAs (char16_t* startPos, char16_t* endPos) {
783:   char16_t ch = *pos;
784:   char16_t* localStartPos = startPos == endPos ? NULL : startPos;
785:   char16_t* localEndPos = startPos == endPos ? NULL : endPos;
786: 
787:   if (ch == 'a') {
788:     pos += 2;
789:     ch = commentWhitespace(true);
790:     startPos = pos;
791: 
792:     if (!isQuote(ch)) {
793:       ch = readToWsOrPunctuator(ch);
794:     }
795:     // export { mod as "identifer" } from
796:     // export { mod as "@notid" } from
797:     // export { mod as "spa ce" } from
798:     // export { mod as " space" } from
799:     // export { mod as "space " } from
800:     // export { mod as "not~id" } from
801:     // export { mod as "%notid" } from
802:     else {
803:       stringLiteral(ch);
804:       pos++;
805:     }
806: 
807:     endPos = pos;
808: 
809:     ch = commentWhitespace(true);
810:   }
811: 
812:   if (pos != startPos)
813:     addExport(startPos, endPos, localStartPos, localEndPos);
814:   return ch;
815: }
