927: char16_t commentWhitespace (bool br) {
928:   char16_t ch;
929:   do {
930:     ch = *pos;
931:     if (ch == '/') {
932:       char16_t next_ch = *(pos + 1);
933:       if (next_ch == '/')
934:         lineComment();
935:       else if (next_ch == '*')
936:         blockComment(br);
937:       else
938:         return ch;
939:     }
940:     else if (br ? !isBrOrWs(ch) : !isWsNotBr(ch)) {
941:       return ch;
942:     }
943:   } while (pos++ < end);
944:   return ch;
945: }
