947: void templateString () {
948:   while (pos++ < end) {
949:     char16_t ch = *pos;
950:     if (ch == '$' && *(pos + 1) == '{') {
951:       pos++;
952:       openTokenStack[openTokenDepth].token = TemplateBrace;
953:       openTokenStack[openTokenDepth++].pos = pos;
954:       return;
955:     }
956:     if (ch == '`') {
957:       if (openTokenStack[--openTokenDepth].token != Template)
958:         syntaxError();
959:       return;
960:     }
961:     if (ch == '\\')
962:       pos++;
963:   }
964:   syntaxError();
965: }
