967: // pos AT the opening backtick. A no-substitution template literal (no ${...})
968: // is a constant string, so a dynamic import can record it as a safe specifier.
969: // On success consumes it, leaves pos AT the closing backtick and returns true.
970: // On a substitution or EOF restores pos and returns false, leaving the literal
971: // to the main loop's template handling.
972: bool noSubstitutionTemplate () {
973:   char16_t* startPos = pos;
974:   while (pos++ < end) {
975:     char16_t ch = *pos;
976:     if (ch == '`')
977:       return true;
978:     if (ch == '\\') {
979:       pos++;
980:       continue;
981:     }
982:     if (ch == '$' && *(pos + 1) == '{')
983:       break;
984:   }
985:   pos = startPos;
986:   return false;
987: }
