989: void blockComment (bool br) {
990:   pos++;
991:   while (pos++ < end) {
992:     char16_t ch = *pos;
993:     if (!br && isBr(ch))
994:       return;
995:     if (ch == '*' && *(pos + 1) == '/') {
996:       pos++;
997:       return;
998:     }
999:   }
1000: }
