1010: void stringLiteral (char16_t quote) {
1011:   while (pos++ < end) {
1012:     char16_t ch = *pos;
1013:     if (ch == quote)
1014:       return;
1015:     if (ch == '\\') {
1016:       ch = *++pos;
1017:       if (ch == '\r' && *(pos + 1) == '\n')
1018:         pos++;
1019:     }
1020:     else if (isBr(ch))
1021:       break;
1022:   }
1023:   syntaxError();
1024: }
