1026: char16_t regexCharacterClass () {
1027:   while (pos++ < end) {
1028:     char16_t ch = *pos;
1029:     if (ch == ']')
1030:       return ch;
1031:     if (ch == '\\')
1032:       pos++;
1033:     else if (ch == '\n' || ch == '\r')
1034:       break;
1035:   }
1036:   syntaxError();
1037:   return '\0';
1038: }
