1040: void regularExpression () {
1041:   while (pos++ < end) {
1042:     char16_t ch = *pos;
1043:     if (ch == '/')
1044:       return;
1045:     if (ch == '[')
1046:       ch = regexCharacterClass();
1047:     else if (ch == '\\')
1048:       pos++;
1049:     else if (ch == '\n' || ch == '\r')
1050:       break;
1051:   }
1052:   syntaxError();
1053: }
