1055: char16_t readToWsOrPunctuator (char16_t ch) {
1056:   do {
1057:     if (isBrOrWs(ch) || isPunctuator(ch))
1058:       return ch;
1059:   } while (ch = *(++pos));
1060:   return ch;
1061: }
